        my_pos = as_point(first_present(obs, ("pos", "position", "loc", "location"), None))
    if my_pos is None:
        return [0, 0]

    mode = first_present(obs, ("mode", "task", "game_type", "scenario"), "")
    mode = mode if isinstance(mode, str) else ""

    resources = []
    for key in ("resources", "resource_tiles", "goals", "targets", "objects", "items", "food", "coins"):
        val = first_present(obs, (key,), None)
        if isinstance(val, list):
            resources.extend([p for p in (as_point(x) for x in val) if p is not None])

    enemies = []
    for key in ("enemies", "opponents", "enemy_units", "others", "hazards", "threats"):
        val = first_present(obs, (key,), None)
        if isinstance(val, list):
            enemies.extend([p for p in (as_point(x) for x in val) if p is not None])

    allies = []
    for key in ("allies", "teammates", "friends", "ally_units"):
        val = first_present(obs, (key,), None)
        if isinstance(val, list):
            allies.extend([p for p in (as_point(x) for x in val) if p is not None])

    walls = set()
    for key in ("walls", "obstacles", "blocked", "blocks"):
        val = first_present(obs, (key,), None)
        if isinstance(val, list):
            for p in val:
                pt = as_point(p)
                if pt is not None:
                    walls.add(pt)

    # Get map bounds if available
    width = first_present(obs, ("width", "cols", "w"), None)
    height = first_present(obs, ("height", "rows", "h"), None)

    def in_bounds(p):
        if width is not None and (p[0] < 0 or p[0] >= width):
            return False
        if height is not None and (p[1] < 0 or p[1] >= height):
            return False
        return True

