    # Determine primary target
    target = None
    if mode == "pursuit_evasion":
        # Prefer nearest enemy if stronger cues absent; otherwise evade nearest enemy
        enemy_bias = first_present(obs, ("chase", "pursue", "attack"), False)
        enemy_bias = bool(enemy_bias)
        if enemies:
