            if not blocked(np):
                return [mv[0], mv[1]]
        return [0, 0]

    # Greedy step toward target with wall avoidance and slight tie-breaking
    best_move = (0, 0)
    best_score = None
    for mv in moves:
        np = (my_pos[0] + mv[0], my_pos[1] + mv[1])
        if blocked(np):
            continue
