            best_move = mv

    if best_move == (0, 0) and target is not None:
        # last resort: axis-aligned step toward target if safe
        dx = clamp1(sign(target[0] - my_pos[0]))
        dy = clamp1(sign(target[1] - my_pos[1]))
        for mv in ((dx, 0), (0, dy), (dx, dy), (0, 0)):
